import{t as e}from"./utils-COoNfFoj.js";var t={slug:`will-mctighe`,influencerName:`Will McTighe`,influencerHandle:`@will-mctighe`,influencerAvatarUrl:`${e}/will-mctighe-avatar.jpeg`,heroDescription:`Will loves running up hills but Google Maps only optimizes for the fastest route, leaving him stuck repeating the same three hills near his San Francisco home for four years. Fed up, he used Perplexity Max to build his own version of Google Maps that finds the hilliest routes possible.`,assetTitle:`SF Grade Atlas`,screenshotUrl:`${e}/will-mctighe.png`,remixUrl:`https://www.perplexity.ai/computer/a/sf-grade-atlas-O_5LdpufQLOTF6U7p8FITw`,promptTitle:`Try Will's prompt`,promptText:`Build a 3D map of San Francisco showing each hill’s grade and incline. When I hover over a block, show how steep the street is in a popup, and color the block on a scale from green (flat) to red (steepest in the city). Make it interactive: let me set a start and end destination plus my average mile pace, and have it output distance, a calculated run time based on pace, and total elevation gain/loss. Also surface one alternate route with steeper elevation — up to 100% slower than the optimal route.`};export{t as default};
